/**
 * Bundled font faces (SIL OFL) and their loading as base64 @font-face data.
 *
 * P5: every family any of the 13 v1 packs uses is bundled, so no pack falls
 * back to a system font (a test asserts this for every pack).
 * Two kinds of source:
 *  - asset:  a TTF from a pinned @expo-google-fonts package, bundled by Metro
 *            and read as base64 at runtime (the P1 path).
 *  - inline: a Latin subset generated by scripts/subset-fonts.mjs as a base64
 *            TypeScript module. Used for the four Korean/Japanese families
 *            whose full files exceed MAX_FONT_BASE64 (Gaegu, Gowun Dodum,
 *            Mochiy Pop One, Zen Maru Gothic). Before P5 the Gaegu faces were
 *            4.2M and 3.9M base64 characters, so loadFaces skipped them and
 *            the default pack's headers used a system font.
 * Licences and notices: docs/licenses/FONTS.md, generated/fontLicenses.ts.
 *
 * `weight` is the CSS weight SLOT a face fills (400 or 700, as
 * fontFaceDataSchema allows). A pack asking for headerWeight 600 gets the
 * 700 slot (CSS font matching picks the nearest heavier face), so Fredoka's
 * SemiBold file fills the 700 slot: that is the weight Blackout Gel was
 * designed with.
 */
// Deep imports: each package's index would bundle every weight (megabytes of TTFs).
import { AtkinsonHyperlegible_400Regular } from '@expo-google-fonts/atkinson-hyperlegible/400Regular';
import { AtkinsonHyperlegible_400Regular_Italic } from '@expo-google-fonts/atkinson-hyperlegible/400Regular_Italic';
import { AtkinsonHyperlegible_700Bold } from '@expo-google-fonts/atkinson-hyperlegible/700Bold';
import { Caveat_700Bold } from '@expo-google-fonts/caveat/700Bold';
import { Cinzel_400Regular } from '@expo-google-fonts/cinzel/400Regular';
import { Cinzel_700Bold } from '@expo-google-fonts/cinzel/700Bold';
import { CormorantGaramond_700Bold_Italic } from '@expo-google-fonts/cormorant-garamond/700Bold_Italic';
import { CrimsonPro_400Regular } from '@expo-google-fonts/crimson-pro/400Regular';
import { CrimsonPro_400Regular_Italic } from '@expo-google-fonts/crimson-pro/400Regular_Italic';
import { CrimsonPro_700Bold } from '@expo-google-fonts/crimson-pro/700Bold';
import { DancingScript_700Bold } from '@expo-google-fonts/dancing-script/700Bold';
import { Delius_400Regular } from '@expo-google-fonts/delius/400Regular';
import { DeliusSwashCaps_400Regular } from '@expo-google-fonts/delius-swash-caps/400Regular';
import { EBGaramond_400Regular } from '@expo-google-fonts/eb-garamond/400Regular';
import { EBGaramond_400Regular_Italic } from '@expo-google-fonts/eb-garamond/400Regular_Italic';
import { EBGaramond_700Bold } from '@expo-google-fonts/eb-garamond/700Bold';
import { Fredoka_600SemiBold } from '@expo-google-fonts/fredoka/600SemiBold';
import { Itim_400Regular } from '@expo-google-fonts/itim/400Regular';
import { Kalam_700Bold } from '@expo-google-fonts/kalam/700Bold';
import { Lexend_400Regular } from '@expo-google-fonts/lexend/400Regular';
import { Lexend_700Bold } from '@expo-google-fonts/lexend/700Bold';
import { Mulish_400Regular } from '@expo-google-fonts/mulish/400Regular';
import { Mulish_400Regular_Italic } from '@expo-google-fonts/mulish/400Regular_Italic';
import { Mulish_700Bold } from '@expo-google-fonts/mulish/700Bold';
import { NanumGothic_400Regular } from '@expo-google-fonts/nanum-gothic/400Regular';
import { NanumGothic_700Bold } from '@expo-google-fonts/nanum-gothic/700Bold';
import { Nunito_400Regular } from '@expo-google-fonts/nunito/400Regular';
import { Nunito_400Regular_Italic } from '@expo-google-fonts/nunito/400Regular_Italic';
import { Nunito_700Bold } from '@expo-google-fonts/nunito/700Bold';
import { PatrickHand_400Regular } from '@expo-google-fonts/patrick-hand/400Regular';
import { Quicksand_400Regular } from '@expo-google-fonts/quicksand/400Regular';
import { Quicksand_700Bold } from '@expo-google-fonts/quicksand/700Bold';

import { BASE64_PATTERN } from '@/core';

import { MAX_FONT_BASE64, type FontFaceData } from './fontFace';
import { FONT_BASE64 as Gaegu400 } from './generated/fonts/Gaegu_400Regular';
import { FONT_BASE64 as Gaegu700 } from './generated/fonts/Gaegu_700Bold';
import { FONT_BASE64 as GowunDodum400 } from './generated/fonts/GowunDodum_400Regular';
import { FONT_BASE64 as MochiyPopOne400 } from './generated/fonts/MochiyPopOne_400Regular';
import { FONT_BASE64 as ZenMaruGothic400 } from './generated/fonts/ZenMaruGothic_400Regular';
import { FONT_BASE64 as ZenMaruGothic700 } from './generated/fonts/ZenMaruGothic_700Bold';
import type { FontFamily, StylePack } from './schema';

/** Where a face's bytes come from (see the file comment). */
export type FaceSource = { kind: 'asset'; asset: number } | { kind: 'inline'; base64: string };

export interface FontFaceAsset {
  family: FontFamily;
  /** CSS weight slot this face fills. */
  weight: 400 | 700;
  style: 'normal' | 'italic';
  source: FaceSource;
}

const asset = (family: FontFamily, weight: 400 | 700, style: 'normal' | 'italic', id: number): FontFaceAsset => ({
  family,
  weight,
  style,
  source: { kind: 'asset', asset: id },
});
const inline = (family: FontFamily, weight: 400 | 700, base64: string): FontFaceAsset => ({
  family,
  weight,
  style: 'normal',
  source: { kind: 'inline', base64 },
});

/**
 * One row per face. Body families get regular, bold and (where the family
 * has one) italic; header-only families get just the slot their pack uses.
 * Families with a single regular file (Itim, Patrick Hand, Delius...) get
 * synthesized bold/italic from the WebView, like before.
 */
export const BUNDLED_FACES: readonly FontFaceAsset[] = [
  // Pastel Highlight (default): Gaegu headers (Latin subsets), Nunito body.
  inline('Gaegu', 400, Gaegu400),
  inline('Gaegu', 700, Gaegu700),
  asset('Nunito', 400, 'normal', Nunito_400Regular),
  asset('Nunito', 400, 'italic', Nunito_400Regular_Italic),
  asset('Nunito', 700, 'normal', Nunito_700Bold),
  // Color Code: Itim + Lexend (Lexend has no italic family).
  asset('Itim', 400, 'normal', Itim_400Regular),
  asset('Lexend', 400, 'normal', Lexend_400Regular),
  asset('Lexend', 700, 'normal', Lexend_700Bold),
  // Seoul Minimal: Gowun Dodum (Latin subset) + Nanum Gothic (unchanged: Reserved Font Names).
  inline('Gowun Dodum', 400, GowunDodum400),
  asset('Nanum Gothic', 400, 'normal', NanumGothic_400Regular),
  asset('Nanum Gothic', 700, 'normal', NanumGothic_700Bold),
  // Light Academia: Cormorant Garamond bold italic headers + EB Garamond body.
  asset('Cormorant Garamond', 700, 'italic', CormorantGaramond_700Bold_Italic),
  asset('EB Garamond', 400, 'normal', EBGaramond_400Regular),
  asset('EB Garamond', 400, 'italic', EBGaramond_400Regular_Italic),
  asset('EB Garamond', 700, 'normal', EBGaramond_700Bold),
  // Dark Academia: Cinzel + Crimson Pro (P0).
  asset('Cinzel', 400, 'normal', Cinzel_400Regular),
  asset('Cinzel', 700, 'normal', Cinzel_700Bold),
  asset('Crimson Pro', 400, 'normal', CrimsonPro_400Regular),
  asset('Crimson Pro', 400, 'italic', CrimsonPro_400Regular_Italic),
  asset('Crimson Pro', 700, 'normal', CrimsonPro_700Bold),
  // Blackout Gel: Fredoka (SemiBold file in the 700 slot, see the file comment) + Patrick Hand.
  asset('Fredoka', 700, 'normal', Fredoka_600SemiBold),
  asset('Patrick Hand', 400, 'normal', PatrickHand_400Regular),
  // Cottagecore: Delius Swash Caps + Delius.
  asset('Delius Swash Caps', 400, 'normal', DeliusSwashCaps_400Regular),
  asset('Delius', 400, 'normal', Delius_400Regular),
  // Coquette: Dancing Script + Mulish.
  asset('Dancing Script', 700, 'normal', DancingScript_700Bold),
  asset('Mulish', 400, 'normal', Mulish_400Regular),
  asset('Mulish', 400, 'italic', Mulish_400Regular_Italic),
  asset('Mulish', 700, 'normal', Mulish_700Bold),
  // Kawaii Pop: Mochiy Pop One + Zen Maru Gothic (Latin subsets).
  inline('Mochiy Pop One', 400, MochiyPopOne400),
  inline('Zen Maru Gothic', 400, ZenMaruGothic400),
  inline('Zen Maru Gothic', 700, ZenMaruGothic700),
  // Clear Read (P1): Atkinson Hyperlegible.
  asset('Atkinson Hyperlegible', 400, 'normal', AtkinsonHyperlegible_400Regular),
  asset('Atkinson Hyperlegible', 400, 'italic', AtkinsonHyperlegible_400Regular_Italic),
  asset('Atkinson Hyperlegible', 700, 'normal', AtkinsonHyperlegible_700Bold),
  // Ocean Lines: Caveat + Nunito. Peach Grid: Patrick Hand + Quicksand. Chalkboard: Kalam + Nunito.
  asset('Caveat', 700, 'normal', Caveat_700Bold),
  asset('Quicksand', 400, 'normal', Quicksand_400Regular),
  asset('Quicksand', 700, 'normal', Quicksand_700Bold),
  asset('Kalam', 700, 'normal', Kalam_700Bold),
];

export function facesForPack(p: StylePack): FontFaceAsset[] {
  const families = new Set<FontFamily>([p.fonts.header, p.fonts.body]);
  return BUNDLED_FACES.filter((f) => families.has(f.family));
}

export function missingFamilies(p: StylePack): FontFamily[] {
  const bundled = new Set(BUNDLED_FACES.map((f) => f.family));
  return [p.fonts.header, p.fonts.body].filter((f) => !bundled.has(f));
}

/** The CSS weight slot a header weight maps to (600 and up use the bold face). */
export const headerSlot = (headerWeight: number): 400 | 700 => (headerWeight >= 600 ? 700 : 400);

/** Port for reading a bundled asset as base64 (Expo adapter in fontLoader). */
export type AssetReader = (asset: number) => Promise<string>;

export async function loadFaces(p: StylePack, read: AssetReader): Promise<FontFaceData[]> {
  const out: FontFaceData[] = [];
  for (const f of facesForPack(p)) {
    const base64 = f.source.kind === 'inline' ? f.source.base64 : await read(f.source.asset);
    // Same guard for both kinds: oversize or non-base64 data is skipped, never injected.
    if (base64.length > MAX_FONT_BASE64 || !BASE64_PATTERN.test(base64)) continue;
    out.push({ family: f.family, weight: f.weight, style: f.style, base64 });
  }
  return out;
}
